def sha(p):
    with open(p,'rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()
def append_csv(path,rows,key):
    old=list(csv.DictReader(open(path)));fields=list(old[0]);seen={r[key] for r in old}
    with open(path,'a',newline='') as f:
        w=csv.DictWriter(f,fieldnames=fields)
        for r in rows:
            if r[key] not in seen:w.writerow({k:r.get(k,'') for k in fields});seen.add(r[key])
